function SavePostButton({postId}:{postId:string}){const[saved,setSaved]=useState(false);useEffect(()=>{const ids:string[]=JSON.parse(localStorage.getItem("ideas-bookmarks")||"[]");setSaved(ids.includes(postId))},[postId]);const toggle=()=>{const ids:string[]=JSON.parse(localStorage.getItem("ideas-bookmarks")||"[]");const next=saved?ids.filter(id=>id!==postId):[...new Set([...ids,postId])];localStorage.setItem("ideas-bookmarks",JSON.stringify(next));setSaved(!saved);toast.success(saved?"Removed from Saved":"Post saved.");window.dispatchEvent(new StorageEvent("storage",{key:"ideas-bookmarks"}));};return <Button size="sm" variant={saved?"default":"outline"} onClick={toggle}><Bookmark className="mr-1 size-4"/>{saved?"Saved":"Save Post"}</Button>}

function PostEngagement({post}:{post:Idea}){
 const[me,setMe]=useState<string|null>(null),[reaction,setReaction]=useState<string|null>(null),[likes,setLikes]=useState(0),[dislikes,setDislikes]=useState(0),[likedUsers,setLikedUsers]=useState<any[]>([]),[dislikedUsers,setDislikedUsers]=useState<any[]>([]),[reshared,setReshared]=useState(false),[shares,setShares]=useState(0),[sharedUsers,setSharedUsers]=useState<any[]>([]),[comments,setComments]=useState<any[]>([]),[text,setText]=useState("");
 useEffect(()=>{(async()=>{
  const{data:{user}}=await supabase.auth.getUser();setMe(user?.id||null);
  const[r,c,s,sh]=await Promise.all([
   supabase.from("idea_post_reactions").select("user_id,reaction").eq("post_id",post.id),
   supabase.from("idea_post_comments").select("*").eq("post_id",post.id).order("created_at",{ascending:true}),
   supabase.from("idea_post_reshares").select("user_id").eq("post_id",post.id),
   supabase.from("idea_post_shares").select("id,user_id,channel,created_at").eq("post_id",post.id).order("created_at",{ascending:false})
  ]);
  const rs=r.data||[], shareRows=sh.error?[]:(sh.data||[]);
  const ids=[...new Set([...rs.map(x=>x.user_id),...shareRows.map(x=>x.user_id)])];
  let profiles:any[]=[];if(ids.length){const{data:p}=await supabase.from("idea_profiles").select("user_id,display_name,public_id,first_name,middle_name,last_name,avatar_url").in("user_id",ids);profiles=p||[]}
  const byId=new Map(profiles.map(p=>[p.user_id,p]));const withProfile=(x:any)=>({...x,profile:byId.get(x.user_id)});
  setLikes(rs.filter(x=>x.reaction==="like").length);setDislikes(rs.filter(x=>x.reaction==="dislike").length);
  setLikedUsers(rs.filter(x=>x.reaction==="like").map(withProfile));setDislikedUsers(rs.filter(x=>x.reaction==="dislike").map(withProfile));
  setReaction(user?.id?rs.find(x=>x.user_id===user.id)?.reaction||null:null);setComments(c.data||[]);
  setReshared(!!user?.id&&(s.data||[]).some(x=>x.user_id===user.id));setShares(shareRows.length);setSharedUsers(shareRows.map(withProfile));
 })()},[post.id]);
 const react=async(k:"like"|"dislike")=>{if(!me)return toast.error("Please sign in first.");if(reaction===k){await supabase.from("idea_post_reactions").delete().eq("post_id",post.id).eq("user_id",me);setReaction(null);k==="like"?setLikes(v=>Math.max(0,v-1)):setDislikes(v=>Math.max(0,v-1));return}if(reaction)await supabase.from("idea_post_reactions").delete().eq("post_id",post.id).eq("user_id",me);const{error}=await supabase.from("idea_post_reactions").insert({post_id:post.id,user_id:me,reaction:k});if(error)toast.error(error.message);else{if(reaction==="like")setLikes(v=>Math.max(0,v-1));if(reaction==="dislike")setDislikes(v=>Math.max(0,v-1));k==="like"?setLikes(v=>v+1):setDislikes(v=>v+1);setReaction(k)}};
 const reshare=async()=>{if(!me)return toast.error("Please sign in first.");if(reshared){await supabase.from("idea_post_reshares").delete().eq("post_id",post.id).eq("user_id",me);setReshared(false)}else{const{error}=await supabase.from("idea_post_reshares").insert({post_id:post.id,user_id:me});if(error)toast.error(error.message);else setReshared(true)}};
 const share=async()=>{
  if(!me)return toast.error("Please sign in first.");
  let slug=String(post.slug||"").trim();
  const title=String(post.title||"").trim();
  if(title.toLowerCase().includes("google september 2026 spam update"))slug="google-september-2026-spam-update";
  else if(!slug){slug=title.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,70)||"anvya-post";slug=slug+"-"+post.id.slice(0,8);try{await supabase.from("idea_posts").update({slug}).eq("id",post.id).eq("user_id",post.user_id)}catch{}}
  const url=new URL("/anvya/"+encodeURIComponent(slug),window.location.origin).href;
  try{
    if(navigator.share)await navigator.share({title:post.title,text:post.title,url});
    else await navigator.clipboard.writeText(url);
  }catch{return}
  const{error}=await supabase.from("idea_post_shares").upsert({post_id:post.id,user_id:me,channel:"web"},{onConflict:"post_id,user_id"});
  if(error){toast.info("Link shared. Share audit will appear after the latest database migration is applied.");return}
  const{data:p}=await supabase.from("idea_profiles").select("user_id,display_name,public_id,first_name,middle_name,last_name,avatar_url").eq("user_id",me).maybeSingle();
  if(!sharedUsers.some(x=>x.user_id===me)){setSharedUsers(v=>[{user_id:me,profile:p},...v]);setShares(v=>v+1)}
  toast.success("Post shared. Original Post ID: "+post.id);
};
const comment=async()=>{if(!me)return toast.error("Please sign in first.");if(!text.trim())return;const{data,error}=await supabase.from("idea_post_comments").insert({post_id:post.id,user_id:me,content:text.trim()}).select().single();if(error)toast.error(error.message);else{setComments(v=>[...v,data]);setText("")}};
 return <div className="mt-4 rounded-2xl border bg-muted/20 p-3">
  <div className="flex flex-wrap items-center gap-2">
   <Button size="sm" variant={reaction==="like"?"default":"outline"} onClick={()=>react("like")}>👍 Like {likes}</Button>
   <Button size="sm" variant={reaction==="dislike"?"default":"outline"} onClick={()=>react("dislike")}>👎 Dislike {dislikes}</Button>
   {likes>0&&<details className="basis-full rounded-xl border bg-background/70 p-2"><summary className="cursor-pointer text-xs font-medium">Liked by {likes} {likes===1?"person":"people"}</summary><div className="mt-2 flex flex-wrap gap-2">{likedUsers.map((u:any)=>{const name=u.profile?.display_name||[u.profile?.first_name,u.profile?.middle_name,u.profile?.last_name].filter(Boolean).join(" ")||u.profile?.public_id||"User";return <Link key={u.user_id} to={"/anvya/profile/"+String(u.user_id)} className="rounded-full border px-2 py-1 text-xs hover:bg-muted">{name}</Link>})}</div></details>}
{dislikes>0&&<details className="basis-full rounded-xl border bg-background/70 p-2"><summary className="cursor-pointer text-xs font-medium">Disliked by {dislikes} {dislikes===1?"person":"people"}</summary><div className="mt-2 flex flex-wrap gap-2">{dislikedUsers.map((u:any)=>{const name=u.profile?.display_name||[u.profile?.first_name,u.profile?.middle_name,u.profile?.last_name].filter(Boolean).join(" ")||u.profile?.public_id||"User";return <Link key={u.user_id} to={"/anvya/profile/"+String(u.user_id)} className="rounded-full border px-2 py-1 text-xs hover:bg-muted">{name}</Link>})}</div></details>}
   <SavePostButton postId={post.id}/>
   <Button size="sm" variant={reshared?"default":"outline"} onClick={reshare}>🔁 {reshared?"Reposted":"Repost"}</Button>
   <Button size="sm" variant="outline" onClick={()=>document.getElementById("comment-"+post.id)?.focus()}>💬 Comment {comments.length}</Button>
   <Button size="sm" variant="outline" onClick={share}>↗️ Share {shares>0?shares:""}</Button>
   {shares>0&&<details className="basis-full rounded-xl border bg-background/70 p-2"><summary className="cursor-pointer text-xs font-medium">Shared by {shares} {shares===1?"person":"people"}</summary><div className="mt-2 flex flex-wrap gap-2">{sharedUsers.map((u:any)=><Link key={u.user_id} to={"/anvya/profile/"+u.user_id} className="inline-flex items-center gap-2 rounded-full border px-2 py-1 text-xs hover:bg-muted"><span className="size-5 overflow-hidden rounded-full bg-muted">{u.profile?.avatar_url?<img src={u.profile.avatar_url} alt="" className="size-full object-cover"/>:<UserCircle2 className="size-full p-0.5 text-muted-foreground"/>}</span><span>{u.profile?.display_name||[u.profile?.first_name,u.profile?.middle_name,u.profile?.last_name].filter(Boolean).join(" ")||u.profile?.public_id||"User"}</span><span className="font-mono text-[10px] text-muted-foreground">post {post.id.slice(0,8)}…</span></Link>)}</div></details>}
  </div>
  <div className="mt-3 flex gap-2"><Input id={"comment-"+post.id} value={text} onChange={e=>setText(e.target.value)} placeholder="Write a comment..." maxLength={2000}/><Button size="sm" onClick={comment}>Comment</Button></div>
  {comments.length>0&&<div className="mt-3 space-y-2">{comments.map(c=><div key={c.id} className="rounded-xl bg-muted/50 p-3 text-sm">{c.content}</div>)}</div>}
 </div>
}

function EventRsvp({post}:{post:Idea}){const[me,setMe]=useState<string|null>(null),[status,setStatus]=useState<string|null>(null),[counts,setCounts]=useState({going:0,interested:0});useEffect(()=>{(async()=>{const{data:{user}}=await supabase.auth.getUser();setMe(user?.id||null);const{data}=await supabase.from("idea_event_rsvps").select("user_id,status").eq("post_id",post.id);const rows=data||[];setCounts({going:rows.filter(x=>x.status==="going").length,interested:rows.filter(x=>x.status==="interested").length});if(user?.id)setStatus(rows.find(x=>x.user_id===user.id)?.status||null)})()},[post.id]);const rsvp=async(next:"going"|"interested")=>{if(!me)return toast.error("Please sign in first.");if(status===next){await supabase.from("idea_event_rsvps").delete().eq("post_id",post.id).eq("user_id",me);setStatus(null);setCounts(v=>({...v,[next]:Math.max(0,v[next]-1)}));return}if(status)await supabase.from("idea_event_rsvps").delete().eq("post_id",post.id).eq("user_id",me);const{error}=await supabase.from("idea_event_rsvps").upsert({post_id:post.id,user_id:me,status:next},{onConflict:"post_id,user_id"});if(error)toast.error(error.message);else{setCounts(v=>({...v,[next]:v[next]+1,...(status?{[status]:Math.max(0,v[status as "going"|"interested"]-1)}:{})}));setStatus(next)}};return <div className="mt-3 flex flex-wrap items-center gap-2"><Button size="sm" variant={status==="going"?"default":"outline"} onClick={()=>rsvp("going")}>I'm Going · {counts.going}</Button><Button size="sm" variant={status==="interested"?"default":"outline"} onClick={()=>rsvp("interested")}>Interested · {counts.interested}</Button></div>}
